orm{f}_{2m}^{2m}+
orm{f\ast \mu_A}_{2m}^{2m}}. \end{align*} We note that $
orm{\mu_A}_1= rac{1}{\abs{A}}\sum_{x\in A}\ind{A}(x)=\abs{A}/\abs{A}=1$, and hence by Young's inequality, $
orm{f\ast \mu_A}_{2m}\leq 
orm{f}_{2m}$, and so \[\sum_{x\in G} \abs{f(x-a_i)-f\ast \mu_A(x)}^{2m}\leq 2^{2m}
orm{f}_{2m}^{2m}.\] It follows that \[ be_{a_1,\ldots,a_k\in A}
orm{ rac{1}{k}\sum_i	au_{a_i}f-f\ast \mu_A}_{2m}^{2m}\leq (64m/k)^m
orm{f}_{2m}^{2m}.\] In particular, if $k\geq 64\epsilon^{-2}m$ then the right-hand side is at most $( rac{\epsilon}{2}
orm{f}_{2m})^{2m}$ as required.

